 * Resolve columns by header label, falling back to known positions.
 * Header rows in this file are unreliable — some have been typed over
 * (Rico's row 1 reads '1/29/2025', Richard's Date header is whitespace),
 * so a label miss must not be fatal.
 */
const LABELS = {
  date: ['DATE'], start: ['SESSION START'], end: ['SESSION END'],
  hours: ['HOURS'], agency: ['AGENCY'], producer: ['PRODUCER'],
  product: ['PRODUCT'], title: ['PROJECT TITLE'], qu: ['QU'],
  workDone: ['WORK DONE'], talents: ['TALENTS'], recordId: ['_AIRTABLE_ID']
};
const FALLBACK = {
  date: 1, start: 2, end: 3, hours: 4, agency: 5,
  producer: 6, product: 7, title: 8, qu: 9, workDone: 10
};

/**
 * Columns 15+ are a helper block feeding the QUERY tab, and it contains a
 * second 'DATE' column filled down for thousands of rows. Labels must only be
 * searched to the left of it, or a tab whose real Date header was typed over
 * (Richard, Rico, Eddieboy all have) resolves to the helper column and the
 * date window stops filtering anything.
 */
function entryAreaWidth(heads) {
  for (let i = 0; i < heads.length; i++) {
    if (heads[i] === 'NAME' && heads[i + 1] === 'DATE') return i;
  }
  return heads.length;
}

function resolveColumns(headerRow) {
  const heads = (headerRow || []).map(norm);
  const limit = entryAreaWidth(heads);
  const cols = {}, byLabel = [];

  Object.keys(LABELS).forEach(function (field) {
    let idx = -1;
    for (let i = 0; i < limit; i++) {
      if (LABELS[field].indexOf(heads[i]) !== -1) { idx = i; break; }
    }
    if (idx === -1 && field === 'recordId') {
      idx = heads.indexOf('_AIRTABLE_ID');          // lives past the helper block
    }
    if (idx !== -1) { cols[field] = idx; byLabel.push(field); }
    else if (FALLBACK[field] !== undefined) cols[field] = FALLBACK[field];
    else cols[field] = -1;
