  'bounce mix & stems': 'Bounce Mix & Elements',
  'bounce mix and stems': 'Bounce Mix & Elements',
  'bounce mix & elements': 'Bounce Mix & Elements'
};

const key = (s) => String(s == null ? '' : s).replace(/\s+/g, ' ').trim().toLowerCase();

const CHOICE_BY_KEY = {};
WORK_DONE_CHOICES.forEach(function (c) { CHOICE_BY_KEY[key(c)] = c; });

/** Tab name -> the Airtable choice, or '' when that engineer has no option. */
function mapEngineer(tabName) {
  const name = ENGINEER_ALIASES[String(tabName).trim()] || String(tabName).trim();
  return ENGINEER_CHOICES.indexOf(name) === -1 ? '' : name;
}

/**
 * Split one free-text Work Done cell into Airtable choices.
 * Matching is exact after normalizing case and whitespace — never fuzzy.
 * A wrong multi-select is far harder to spot later than a missing one.
 */
function matchWorkDone(text) {
  const raw = String(text == null ? '' : text).trim();
  if (!raw) return { matched: [], unmatched: [], raw: raw };

  // Check the whole cell first: a choice can itself contain a separator
  // ('Bounce Mix & Elements', written by hand as 'Bounce Mix and Stems'),
  // and splitting before aliasing would destroy it.
  const whole = CHOICE_BY_KEY[key(raw)] || CHOICE_BY_KEY[key(WORK_DONE_ALIASES[key(raw)] || '')];
  if (whole) return { matched: [whole], unmatched: [], raw: raw };

  const parts = raw.split(/[,;/]+|\s+and\s+/i)
    .map(function (p) { return p.trim(); })
    .filter(Boolean);

  const matched = [], unmatched = [];
  parts.forEach(function (p) {
    const hit = CHOICE_BY_KEY[key(p)] || CHOICE_BY_KEY[key(WORK_DONE_ALIASES[key(p)] || '')];
    if (hit) { if (matched.indexOf(hit) === -1) matched.push(hit); }
    else unmatched.push(p);
  });

  return { matched: matched, unmatched: unmatched, raw: raw };
}

/** True when the matched choices mean a talent should have been named. */
function needsTalents(matched) {
  return (matched || []).some(function (m) { return RECORDING_CHOICES.indexOf(m) !== -1; });
}

