/** Tabs that are not engineer logs. Everything else in the file is one. */
const NON_ENGINEER_TABS = [
  'Form Responses 1', 'QUERY', 'DATA VALIDATION', 'DASHBOARD',
  'QUERY ADJUSTMENTS', 'TIME LOG', '_hitsync'
];

function isEngineerTab(name) {
  return NON_ENGINEER_TABS.indexOf(String(name).trim()) === -1;
}

/** Google serial date -> 'YYYY-MM-DD'. Sheets' epoch is 1899-12-30. */
function serialToISO(serial) {
  if (typeof serial !== 'number' || !isFinite(serial)) return '';
  const ms = Math.round(serial) * 86400000;
  const d = new Date(Date.UTC(1899, 11, 30) + ms);
  return d.toISOString().slice(0, 10);
}

/** Fraction of a day -> 'HH:mm'. 0.875 -> '21:00'. */
function fracToHHMM(v) {
  if (typeof v !== 'number' || !isFinite(v)) return v == null ? '' : String(v).trim();
  let mins = Math.round((v % 1) * 1440);
  if (mins < 0) mins += 1440;
  const h = Math.floor(mins / 60), m = mins % 60;
  return String(h).padStart(2, '0') + ':' + String(m).padStart(2, '0');
}

const norm = (s) => String(s == null ? '' : s).replace(/\s+/g, ' ').trim().toUpperCase();

/**
 * Resolve columns by header label, falling back to known positions.
 * Header rows in this file are unreliable — some have been typed over
 * (Rico's row 1 reads '1/29/2025', Richard's Date header is whitespace),
 * so a label miss must not be fatal.
 */
const LABELS = {
  date: ['DATE'], start: ['SESSION START'], end: ['SESSION END'],
  hours: ['HOURS'], agency: ['AGENCY'], producer: ['PRODUCER'],
  product: ['PRODUCT'], title: ['PROJECT TITLE'], qu: ['QU'],
  workDone: ['WORK DONE'], talents: ['TALENTS'], recordId: ['_AIRTABLE_ID']
};
const FALLBACK = {
  date: 1, start: 2, end: 3, hours: 4, agency: 5,
  producer: 6, product: 7, title: 8, qu: 9, workDone: 10
};

/**
 * Columns 15+ are a helper block feeding the QUERY tab, and it contains a
 * second 'DATE' column filled down for thousands of rows. Labels must only be
 * searched to the left of it, or a tab whose real Date header was typed over
 * (Richard, Rico, Eddieboy all have) resolves to the helper column and the
 * date window stops filtering anything.
 */
function entryAreaWidth(heads) {
  for (let i = 0; i < heads.length; i++) {
    if (heads[i] === 'NAME' && heads[i + 1] === 'DATE') return i;
  }
  return heads.length;
}

function resolveColumns(headerRow) {
  const heads = (headerRow || []).map(norm);
  const limit = entryAreaWidth(heads);
  const cols = {}, byLabel = [];

  Object.keys(LABELS).forEach(function (field) {
    let idx = -1;
    for (let i = 0; i < limit; i++) {
      if (LABELS[field].indexOf(heads[i]) !== -1) { idx = i; break; }
    }
    if (idx === -1 && field === 'recordId') {
      idx = heads.indexOf('_AIRTABLE_ID');          // lives past the helper block
    }
    if (idx !== -1) { cols[field] = idx; byLabel.push(field); }
    else if (FALLBACK[field] !== undefined) cols[field] = FALLBACK[field];
    else cols[field] = -1;
  });

  return { cols: cols, resolvedByLabel: byLabel };
}

/**
 * The QU column is authoritative; the title is the fallback.
 * Titles carry malformed prefixes in the wild: 'QU-QU-16069', 'QU-3798  X',
 * and bare 'QU- ' on work that has no quote at all.
 */
function parseQu(quCell, title) {
  const raw = String(quCell == null ? '' : quCell).trim();
  const t = String(title == null ? '' : title).trim();
  const m = t.match(/^(?:QU[\s-]*)+(\d{3,6})[A-Za-z]?\s*/i);

  let qu = '';
  const direct = raw.match(/(\d{3,6})/);
  if (raw && direct) qu = 'QU-' + direct[1];
  else if (m) qu = 'QU-' + m[1];

  const cleanTitle = m ? t.slice(m[0].length).trim() : t.replace(/^QU[\s-]+/i, '').trim();
  return { qu: qu, cleanTitle: cleanTitle, quFromColumn: Boolean(raw && direct) };
}

/**
 * Turn one tab's raw batchGet values into entries inside [from, to).
 * from/to are 'YYYY-MM-DD' strings, to is exclusive.
 */
function extractEntries(opts) {
  const tab = opts.tab;
  const values = opts.values || [];
  const from = opts.from, to = opts.to;
  if (!values.length) return { entries: [], warnings: ['empty tab'], scanned: 0 };

  const r = resolveColumns(values[0]);
  const c = r.cols;
  const entries = [], warnings = [];
  let scanned = 0;

  for (let i = 1; i < values.length; i++) {
    const row = values[i];
    if (!row || !row.length) continue;
    const iso = serialToISO(row[c.date]);
    if (!iso) continue;
    scanned++;
    if (from && iso < from) continue;
    if (to && iso >= to) continue;

    const parsed = parseQu(row[c.qu], row[c.title]);
    const hours = typeof row[c.hours] === 'number' ? row[c.hours] : parseFloat(row[c.hours]);

    entries.push({
      sheetRow: i + 1,
      tab: tab,
      engineer: tab,
      date: iso,
      sessionStart: fracToHHMM(row[c.start]),
      sessionEnd: fracToHHMM(row[c.end]),
      hours: isFinite(hours) ? hours : null,
      agency: String(row[c.agency] == null ? '' : row[c.agency]).trim(),
      producer: String(row[c.producer] == null ? '' : row[c.producer]).trim(),
      product: String(row[c.product] == null ? '' : row[c.product]).trim(),
      projectTitle: parsed.cleanTitle,
      quoteNumber: parsed.qu,
      quFromColumn: parsed.quFromColumn,
      workDone: String(row[c.workDone] == null ? '' : row[c.workDone]).trim(),
      talents: c.talents >= 0 ? String(row[c.talents] == null ? '' : row[c.talents]).trim() : '',
      recordId: c.recordId >= 0 ? String(row[c.recordId] == null ? '' : row[c.recordId]).trim() : '',
      // 1-based column the record id is written back to; 0 when the tab has no such column
      idColumn: c.recordId >= 0 ? c.recordId + 1 : 0
    });
  }

  if (c.recordId < 0) warnings.push(tab + ': no _airtable_id column, ids cannot be written back');
  if (r.resolvedByLabel.indexOf('qu') === -1) warnings.push(tab + ': no QU column found, fell back to position 10');
  if (r.resolvedByLabel.indexOf('title') === -1) warnings.push(tab + ': no Project Title header, fell back to position 9');

  return { entries: entries, warnings: warnings, scanned: scanned, cols: c };
}

const vocab = { matchWorkDone, mapEngineer, needsTalents, WORK_DONE_CHOICES, RECORDING_CHOICES };


