/**
 * The shapes n8n passes in, and the requests it sends back out.
 * Pure string/object building — no network, so it is all testable offline.
 */

const SHEETS = 'https://sheets.googleapis.com/v4/spreadsheets/';
const AIRTABLE = 'https://api.airtable.com/v0/';

/** A1 column letter for a 1-based index. 1 -> A, 27 -> AA. */
function colLetter(n) {
  let s = '';
  while (n > 0) { const r = (n - 1) % 26; s = String.fromCharCode(65 + r) + s; n = Math.floor((n - 1) / 26); }
  return s;
}

/** Quote a tab name for an A1 range when it needs it. */
function quoteTab(tab) {
  return /^[A-Za-z0-9_]+$/.test(tab) ? tab : "'" + String(tab).replace(/'/g, "''") + "'";
}

/** One call that pulls every engineer tab. Dates as serials, so parsing is unambiguous. */
function buildBatchGetUrl(spreadsheetId, tabs, lastColumn) {
  const col = colLetter(lastColumn || 26);
  const qs = tabs.map(function (t) {
    return 'ranges=' + encodeURIComponent(quoteTab(t) + '!A1:' + col + '9000');
  }).join('&');
  return SHEETS + spreadsheetId + '/values:batchGet?' + qs +
    '&valueRenderOption=UNFORMATTED_VALUE&dateTimeRenderOption=SERIAL_NUMBER';
}

/** batchGet response -> { tabName: values[][] } */
function parseBatchGet(body) {
  const out = {};
  ((body || {}).valueRanges || []).forEach(function (vr) {
    const name = String(vr.range || '').split('!')[0].replace(/^'/, '').replace(/'$/, '').replace(/''/g, "'");
    out[name] = vr.values || [];
  });
  return out;
}

/** Airtable list URL, paginated by the caller. */
function buildListUrl(baseId, tableId, offset) {
  return AIRTABLE + baseId + '/' + tableId + '?pageSize=100' +
    (offset ? '&offset=' + encodeURIComponent(offset) : '');
}

/** Airtable takes 10 records per write. */
function chunk(arr, n) {
  const out = [];
  for (let i = 0; i < arr.length; i += (n || 10)) out.push(arr.slice(i, i + (n || 10)));
  return out;
}

function buildCreateRequests(creates, baseId, tableId) {
  return chunk(creates, 10).map(function (batch) {
    return {
      method: 'POST',
      url: AIRTABLE + baseId + '/' + tableId,
      body: { records: batch.map(function (c) { return { fields: c.fields }; }), typecast: false },
      entries: batch.map(function (c) { return c.entry; })
    };
  });
}

function buildUpdateRequests(updates, baseId, tableId) {
  return chunk(updates, 10).map(function (batch) {
    return {
      method: 'PATCH',
      url: AIRTABLE + baseId + '/' + tableId,
      body: {
        records: batch.map(function (u) { return { id: u.recordId, fields: u.fields }; }),
        typecast: false
      },
      entries: batch.map(function (u) { return u.entry; })
    };
  });
}

/**
 * Write each new record id back into its own row, so the key travels with
 * the row rather than with its position.
 */
function buildWritebackRequest(spreadsheetId, pairs) {
  const data = pairs.map(function (p) {
    return {
      range: quoteTab(p.tab) + '!' + colLetter(p.idColumn) + p.sheetRow,
      values: [[p.recordId]]
    };
  });
  return {
    method: 'POST',
    url: SHEETS + spreadsheetId + '/values:batchUpdate',
    body: { valueInputOption: 'RAW', data: data }
  };
}

/**
 * The live base links Project Title to a Projects table, and its records are
 * codenames (FROZONE) that never match the sheet's descriptive titles. The
 * usable join is the QU, which existing rows already carry alongside their link.
 */
function buildProjectLinkMap(records, quField, linkField) {
  const map = {};
  (records || []).forEach(function (r) {
    const f = r.fields || {};
    const qu = String(f[quField || 'Reference Number'] || '').trim();
    const link = f[linkField || 'Project Title'];
    if (!qu || !Array.isArray(link) || !link.length) return;
    const digits = (qu.match(/(\d{3,6})/) || [])[1];
    if (!digits) return;
    const key = 'QU-' + digits;
    if (!map[key]) map[key] = link[0];
  });
  return map;
}

