/** Talents is required when the work involves any of these. */
const RECORDING_CHOICES = ['Studio Recording', 'Remote Recording', 'Van Recording'];

/** Sheet tab name -> Airtable 'Logged by' choice. Only differences are listed. */
const ENGINEER_ALIASES = { 'Eli': 'Elijah' };

/** Engineers that exist as an Airtable choice. Tabs outside this list cannot sync. */
const ENGINEER_CHOICES = [
  'Daryl', 'Eddieboy', 'Elijah', 'Glenn', 'Howard', 'Josiah', 'Philip',
  'Regie', 'Richard', 'Rico', 'Tara', 'Topet', 'Vener', 'Whannie'
