/** Fraction of a day -> 'HH:mm'. 0.875 -> '21:00'. */
function fracToHHMM(v) {
  if (typeof v !== 'number' || !isFinite(v)) return v == null ? '' : String(v).trim();
  let mins = Math.round((v % 1) * 1440);
  if (mins < 0) mins += 1440;
  const h = Math.floor(mins / 60), m = mins % 60;
  return String(h).padStart(2, '0') + ':' + String(m).padStart(2, '0');
}

