const lines = [d.summary];
if (d.warnings && d.warnings.length) {
  lines.push('');
  lines.push('Warnings:');
  d.warnings.slice(0, 10).forEach(w => lines.push('  ' + w));
}
return [{ json: { mode: d.mode, counts: d.counts, message: lines.join('\n') } }];
